code.binary-search:
def binary_search(values, target):
    if not values:
        return -1
    def search(low, high):
        middle = (low+high)//2

        if values[middle] == target:
            return middle

        if low > high:
            return -1

        if values[low] <= target < values[middle]:
            return search(low, middle-1)
        return search(middle+1, high)


    return search(0, len(values) - 1)

code.count-in-nested:
def count_value(nested, target):

    if not nested:
        return 0

    def count_value_helper(nested, target, count):
        if not nested:
            return count

        for nest in nested:

            if nest == target:
                count += 1
            if isinstance(nest, list):
                count = count_value_helper(nest, target, count)
        return count

    return count_value_helper(nested, target, 0)

code.digit-sum:
def digit_sum(n):

    def digit_sum_helper(curr_sum, curr_n):
        if curr_n == 0:
            return curr_sum
        curr_sum += curr_n%10
        return digit_sum_helper(curr_sum, curr_n//10)

    return digit_sum_helper(0, n)

code.factorial:
def factorial(n):
    if n == 0:
        return 1

    return n * factorial(n-1)

code.fibonacci:
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-2) + fibonacci(n-1)

code.flatten:
def flatten(nested):



    for nest in nested:
        if not isinstance(nest, list):
            yield nest
        else:
            yield from flatten(nest)

code.gcd:
def gcd(a, b):

    if b == 0:
        return a

    return gcd(b, a%b)

code.index-of-max:
def index_of_max(values):

    def index_of_max_helper(index, max_val, best_index):
        if index == len(values):
            return best_index

        if values[index] > max_val:
            max_val = values[index]
            best_index = index

        return index_of_max_helper(index+1, max_val, best_index)
    return index_of_max_helper(0, float('-inf'), 0)

code.is-palindrome:
def is_palindrome(s):

    def is_pal_helper(left, right):
        if left > right:
            return True

        if s[left] != s[right]:
            return False
        return is_pal_helper(left+1, right-1)
    return is_pal_helper(0, len(s)-1)

code.is-sorted:
def is_sorted(values):
    if not values:
        return True
    def is_sorted_helper(index):
        if index+1 == len(values):
            return True

        if values[index] > values[index+1]:
            return False

        return is_sorted_helper(index+1)

    return is_sorted_helper(0)

code.max-of-list:
def max_of_list(values):

    max_val = float('-inf')

    def max_of_list_helper(index, max_val):
        if index == len(values):
            return max_val

        if values[index] > max_val:
            max_val = values[index]
        return max_of_list_helper(index+1, max_val)
    return max_of_list_helper(0, -10000)

code.power:
def power(base, exponent):

    if exponent == 0:
        return 1

    return base * power(base, exponent-1)

code.remove-duplicates-sorted:
def remove_duplicates(values):
    if not values:
        return []
    def remove_duplicates_helper(new_arr, index):
        if index == len(values):
            return new_arr

        if values[index] != values[index-1]:
            new_arr.append(values[index])

        return remove_duplicates_helper(new_arr, index+1)

    return remove_duplicates_helper([values[0]], 1)

code.reverse-string:
def reverse_string(s):

    if not s:
        return ""

    def reverse_helper(index):
        if index == -1:
            return ""
        return s[index] + "" + reverse_helper(index-1)
    return reverse_helper(len(s)-1)

